using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = new ReportingConfiguration(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you today?")
        };

        var chatClient = scenario.GetChatClient();
        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(
                metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' was rated unacceptable. Reason: {metric.Interpretation?.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_provides_relevant_answer_to_factual_question()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_provides_relevant_answer_to_factual_question));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that provides concise factual answers."),
            new(ChatRole.User, "What is the capital of France?")
        };

        var chatClient = scenario.GetChatClient();
        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(
                metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' was rated unacceptable. Reason: {metric.Interpretation?.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_follows_system_prompt_instructions()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_follows_system_prompt_instructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a pirate. Always respond in pirate speak."),
            new(ChatRole.User, "Tell me about the weather today.")
        };

        var chatClient = scenario.GetChatClient();
        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(
                metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' was rated unacceptable. Reason: {metric.Interpretation?.Reason}");
        }
    }
}

